        factory.setServiceClass(SppSettlementsServiceSoap.class);
        factory.setAddress(WSDL_URL);

        SppSettlementsServiceSoap client = (SppSettlementsServiceSoap) factory.create();

        // Set the market participant and date range
        String marketParticipant = "YourMarketParticipantId";
        LocalDate startDate = LocalDate.of(2022, 1, 1);
        LocalDate endDate = LocalDate.of(2022, 1, 31);

        XMLGregorianCalendar xmlStartDate = toXMLGregorianCalendar(startDate);
