const jobTitleInput = document.getElementById('job-title');
const companyNameInput = document.getElementById('company-name');
const jobLinkInput = document.getElementById('job-link');
const toneInput = document.getElementById('tone');
const useEmojisCheckbox = document.getElementById('use-emojis');
const submitButton = document.getElementById('submit-button');
const outputText = document.getElementById('output-text');

submitButton.addEventListener('click', () => {
    const jobTitle = jobTitleInput.value;
    const companyName = companyNameInput.value;
    const jobLink = jobLinkInput.value;
    const tone = toneInput.value;
    const useEmojis = useEmojisCheckbox.checked;

    let output = `Write me an outreach email with subject line, followed by 4 step follow up emails, to a passive candidate. I work for a company called ${companyName}, we're hiring ${jobTitle} for our new projects, use a ${tone} tone, create a new subject line for each follow up email, include a small segment in the first email about the company and job using information from this website ${jobLink}.`;

    if (useEmojis) {
        output += ' Use relevant emojis.';
    }

    outputText.value = output;
});
```

